// تحقّق دفاعي: أي كلمة فاضية أو مكررة توقف الرن بدل ما تطلّع صف فاضي في التقرير.
const seen = {};
keywords.forEach((k, i) => {
  const kw = String(k.keyword || '').trim();
  if (!kw) throw new Error('Keywords: الصف رقم ' + (i + 1) + ' من غير كلمة مفتاحية.');
  if (seen[kw]) throw new Error('Keywords: الكلمة "' + kw + '" مكررة.');
  seen[kw] = 1;
  k.keyword = kw;
  k.group   = String(k.group || 'بدون قسم').trim();
  k.page    = String(k.page || '').trim();
  k.article = String(k.article || '').trim();
});

return [{ json: { keywords, keywordCount: keywords.length } }];

// بيحوّل صفوف الشيت لذاكرة تاريخية + بيسجّل مقاس الشيت القديم عشان الكتابة
// الجديدة تمسح أي بقايا أعمدة/صفوف قديمة.
//
// قراءة الخانة:
//   فاضية        = ما اتسحبتش أصلًا (هنحاول تاني)
//   '-'          = اتسحبت من جوجل ومفيش ظهور مؤكد
//   رقم          = ترتيب مؤكد
const rows = Array.isArray($json.values) ? $json.values : null;

// Fetch Sheet شغّال بـ continueRegularOutput، فلو فشل بيوصلنا error.
// مهم جدًا نفرّق بين "الشيت فاضي" و"مقدرناش نقراه": في الحالة التانية ممنوع
// نكتب على الشيت، لأن الكتابة هتمسح كل الأرشيف.
const fetchError = ($json && $json.error !== undefined && $json.error !== null)
  ? (typeof $json.error === 'string' ? $json.error : JSON.stringify($json.error).slice(0, 300))
  : '';
const sheetError = fetchError || (rows === null ? 'رد Google Sheets مالهوش الشكل المتوقع (مفيش values).' : '');

// أرقام عربية/هندية + الفاصلة العشرية العربية + فواصل الآلاف.
const AR_DIGITS = { '٠':'0','١':'1','٢':'2','٣':'3','٤':'4','٥':'5','٦':'6','٧':'7','٨':'8','٩':'9',
                    '۰':'0','۱':'1','۲':'2','۳':'3','۴':'4','۵':'5','۶':'6','۷':'7','۸':'8','۹':'9' };

function num(v) {
  if (v === '' || v === undefined || v === null) return null;
  if (typeof v === 'number') return isFinite(v) ? v : null;
  let s = String(v);
  s = s.replace(/[٠-٩۰-۹]/g, ch => AR_DIGITS[ch] || ch);   // أرقام عربية → لاتينية
  s = s.replace(/[\u200B-\u200F\u202A-\u202E\u2066-\u2069\uFEFF]/g, ''); // محارف اتجاه
  s = s.replace(/[\u066C,\s]/g, '');                        // فواصل الآلاف
  s = s.replace(/[\u066B\u060C]/g, '.');                   // فاصلة عشرية عربية
  s = s.replace(/[^0-9.+-]/g, '');
  if (s === '' || s === '-' || s === '.' || s === '+') return null;
  const n = Number(s);
  return isFinite(n) ? n : null;
}

const hist = { monthKeys: [], byRow: {} };
let extentRows = 0, extentCols = 0, dataRows = 0;

if (!sheetError && rows.length) {
  extentRows = rows.length;
  rows.forEach(r => { extentCols = Math.max(extentCols, (r || []).length); });
}

if (!sheetError && rows.length > 1) {
  const head = rows[0].map(h => String(h == null ? '' : h).trim());
  const cols = {};
  head.forEach((h, i) => {
    const mm = h.match(/^(\d{4}-\d{2})\s+(Pos|Impr)$/);
    if (mm) {
      cols[mm[1]] = cols[mm[1]] || {};
      cols[mm[1]][mm[2]] = i;
      if (hist.monthKeys.indexOf(mm[1]) === -1) hist.monthKeys.push(mm[1]);
    }
  });
  hist.monthKeys.sort();

  for (let r = 1; r < rows.length; r++) {
    const row = rows[r] || [];
    const country = String(row[0] == null ? '' : row[0]).trim();
    const keyword = String(row[2] == null ? '' : row[2]).trim();
    if (!keyword) continue;
    dataRows++;
    const rec = {};
    hist.monthKeys.forEach(mk => {
      const c = cols[mk] || {};
      const rawP = c.Pos === undefined ? undefined : row[c.Pos];
      const rawI = c.Impr === undefined ? undefined : row[c.Impr];
      const p = (rawP === undefined || rawP === null) ? '' : String(rawP).trim();
      const imp = num(rawI);
      rec[mk] = {
        position:    (p === '' || p === '-' || p === '—' || p === '–') ? null : num(rawP),
        impressions: imp === null ? 0 : imp,
        filled:      p !== '',
      };
    });
    hist.byRow[country + '||' + keyword] = rec;
  }
}

return [{ json: {
  __history: hist,
  __sheetError: sheetError,
  __extent: { rows: extentRows, cols: extentCols },
  __sheetStats: { dataRows, periodsInSheet: hist.monthKeys.length },
} }];

// بيبني قائمة الطلبات (كلمة × شهر) اللي هتتبعت لجوجل.
// الفرق عن النسخة القديمة:
//  1) نهاية الفترة بتتقارن بآخر يوم فيه بيانات نهائية عند جوجل (من نود
//     GSC Freshness) مش بتخمين LAG_DAYS — فمش بنطلب شهر لسه ما اكتملش.
//  2) كل طلب معاه taskId + taskIndex عشان الربط بين الطلب والرد يبقى مؤكد.
const cfg   = $('Config').first().json;
const kws   = $('Keywords').first().json.keywords;
const hist  = $('Read Sheet').first().json.__history || { byRow: {} };
const fresh = $('Freshness Guard').first().json;

const MON = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const latest = fresh.latestDataDate;               // 'YYYY-MM-DD'

const today = new Date();
const all = [];
let y = today.getUTCFullYear(), m = today.getUTCMonth();
for (let i = 0; i < 40; i++) {
  const lastDay = new Date(Date.UTC(y, m + 1, 0)).getUTCDate();
  const endDate = new Date(Date.UTC(y, m, lastDay)).toISOString().slice(0, 10);
  // الشهر بيتحسب مقفول لما آخر يوم فيه يكون عند جوجل بيانات نهائية عنه.
  if (endDate <= latest) {
    all.push({
      key: y + '-' + String(m + 1).padStart(2, '0'),
      label: MON[m] + ' ' + String(y).slice(2),
      startDate: new Date(Date.UTC(y, m, 1)).toISOString().slice(0, 10),
      endDate,
    });
  }
  m--; if (m < 0) { m = 11; y--; }
}
const periods = all.slice(0, cfg.columns).reverse();

if (!periods.length) {
  throw new Error('Build Tasks: مفيش ولا شهر مقفول عند جوجل (آخر يوم بيانات: ' +
                  latest + ') — الرن اتوقف قبل ما يطلّع تقرير فاضي.');
}

const forceFrom = periods.length - (cfg.refetchLast || 0);

const out = [];
let taskIndex = 0;
cfg.countries.forEach((c, ci) => {
  kws.forEach((k, ki) => {
    const rec = hist.byRow[c.name + '||' + k.keyword] || {};
    periods.forEach((p, pIdx) => {
      const cell = rec[p.key];
      // خانة متأكدين منها (فيها رقم) وقديمة → مش محتاجين نعيد سحبها.
      if (cell && cell.filled && cell.position !== null && pIdx < forceFrom) return;
      out.push({ json: {
        taskId: c.name + '||' + k.keyword + '||' + p.key,
        taskIndex: taskIndex++,
        period: p.key, label: p.label,
        startDate: p.startDate, endDate: p.endDate,
        keyword: k.keyword, page: k.page || '', group: k.group,
        countryCode: c.code, countryName: c.name, ci, ki, pIdx,
        __periods: periods,
        __latestDataDate: latest,
      } });
    });
  });
});

if (!out.length) {
  return [{ json: { __noFetch: true, __periods: periods, __latestDataDate: latest, taskIndex: 0 } }];
}
return out;

// بيراجع ردود السحبة الأولى ويحدد أنهي طلبات محتاجة محاولة تانية.
// الطلب بيتعاد لو: فشل (429 / 403 / شبكة) أو ملقاش رد أصلاً.
// الطلب اللي رجع سليم — حتى لو مفيش فيه ظهور — مش بيتعاد.
// ---------------------------------------------------------------------------
// مكتبة الربط والتحقق بين طلبات GSC وردودها.
// (بتتحقن أوتوماتيك في نودات الكود وقت البناء — متعدّلهاش في n8n)
// ---------------------------------------------------------------------------

// n8n بيحط pairedItem على كل عنصر خارج من HTTP Request بيقول جه من أنهي
// عنصر داخل. ده أضمن من الاعتماد على الترتيب، لأن الرد ممكن يتقسّم أو يتلم.
function srcIndex(item, fallbackIndex) {
  const p = item ? item.pairedItem : undefined;
  if (typeof p === 'number') return p;
  if (p && typeof p.item === 'number') return p.item;
  if (Array.isArray(p) && p.length && p[0] && typeof p[0].item === 'number') return p[0].item;
  return fallbackIndex;
}

function errText(e) {
  if (e === undefined || e === null) return '';
  if (typeof e === 'string') return e.slice(0, 300);
  if (e.message) return String(e.message).slice(0, 300);
  try { return JSON.stringify(e).slice(0, 300); } catch (x) { return String(e).slice(0, 300); }
}

// بيصنّف رد واحد من GSC:
//   ok        = رد سليم من جوجل (سواء فيه صفوف أو مفيش)
//   error     = الطلب فشل (429 / 403 / شبكة / توكن)
//   missing   = مفيش رد أصلاً للطلب ده
function classify(res, rowLimit) {
  if (!res) return { state: 'missing', reason: 'مفيش رد للطلب ده' };
  const j = res.json || {};
  if (j.error !== undefined && j.error !== null) {
    return { state: 'error', reason: errText(j.error) || 'خطأ من جوجل' };
  }
  // GSC بيرجّع {} لما مفيش بيانات — ده رد ناجح مش خطأ.
  const rows = Array.isArray(j.rows) ? j.rows : [];
  // الرد بيتقصّ عند rowLimit اللي احنا طلبناه. المقارنة كانت متثبّتة على 900
  // والـ rowLimit الفعلي 500 — يعني الحارس ده عمره ما كان بيشتغل، وأي كلمة
  // ليها صفحات أكتر من الحد كان مجموعها بيطلع ناقص من غير ما حد يعرف.
  const limit = Number(rowLimit) > 0 ? Number(rowLimit) : 0;
  return { state: 'ok', rows, truncated: limit > 0 && rows.length >= limit };
}

// بيربط ردود نود HTTP بطلباتها.
// لو عدد الردود = عدد الطلبات → pairedItem وإلا الترتيب.
// لو العدد مختلف → pairedItem بس، وأي طلب ملقاش رد بيتعلّم missing.
// بنرجّع map من taskIndex → { state, rows | reason }
function pairResults(tasks, results, rowLimit) {
  const strict = results.length !== tasks.length;
  const map = {};
  const stats = { results: results.length, tasks: tasks.length, strict, unpaired: 0 };
  results.forEach((r, i) => {
    const idx = strict ? srcIndex(r, -1) : srcIndex(r, i);
    if (idx < 0 || idx >= tasks.length || !tasks[idx]) { stats.unpaired++; return; }
    const t = tasks[idx].json || {};
    if (t.taskId === undefined) { stats.unpaired++; return; }
    // أول رد بيكسب: لو حصل تكرار في pairedItem مانستبدلش رد سليم بواحد فاشل.
    const c = classify(r, rowLimit);
    if (!map[t.taskId] || (map[t.taskId].state !== 'ok' && c.state === 'ok')) {
      map[t.taskId] = c;
    }
  });
  return { map, stats };
}

// ---- تطبيع الروابط للمقارنة ----
function normUrl(u) {
  let s = String(u == null ? '' : u);
  for (let i = 0; i < 2; i++) {                 // فك ترميز مزدوج لو موجود
    try {
      const d = decodeURIComponent(s);
      if (d === s) break;
      s = d;
    } catch (e) { break; }
  }
  s = s.trim().toLowerCase();
  s = s.replace(/[#?].*$/, '');                 // شيل الأنكور والباراميترز
  s = s.replace(/^https?:\/\//, '').replace(/^www\./, '');
  s = s.replace(/\/index\.(html?|php)$/, '/');
  s = s.replace(/\/+$/, '');
  return s;
}

// ---- تجميع صفوف الصفحات لرقم واحد على مستوى الموقع ----
// جوجل بيرجّع صف لكل صفحة: متوسط موضع الصفحة دي + عدد ظهورها للكلمة.
// الرقم اللي واجهة Search Console بتعرضه للكلمة من غير فلتر صفحة هو المتوسط
// الموزون بعدد الظهور:
//
//     الموضع = مجموع(الموضع × الظهور) ÷ مجموع(الظهور)
//     الظهور = مجموع الظهور
//
// النسخة القديمة كانت بتاخد "أقل موضع" بين الصفحات وظهور الصفحة دي لوحدها.
// ده رقم صفحة واحدة متقفشة من بين ٥٠٠ صفحة — بيطلّع موضع أحسن من الحقيقة
// وظهور أقل منها بكتير. ده بالظبط سبب "POS 10 / IMP 1" في التقرير مقابل
// "20.9 / 144" في الواجهة.
//
// ملحوظة: مجموع الظهور على مستوى الصفحات ممكن يزيد شوية عن رقم الواجهة لو
// أكتر من صفحة من الموقع ظهرت في نفس نتيجة البحث. الرقم المضبوط تمامًا
// بييجي من الصفحة المستهدفة (page) — عشان كده كل كلمة المفروض يكون ليها رابط.
function aggregateRows(rows) {
  let impressions = 0, clicks = 0, weighted = 0;
  rows.forEach(r => {
    const im = Number(r.impressions) || 0;
    impressions += im;
    clicks      += Number(r.clicks) || 0;
    weighted    += Number(r.position) * im;
  });
  return {
    impressions,
    clicks,
    position: impressions > 0 ? weighted / impressions : null,
  };
}

const round1 = v => (v === null || v === undefined) ? null : Math.round(Number(v) * 10) / 10;

// بيطلع نتيجة خانة واحدة من رد جوجل.
// verdict:
//   ranked  = فيه ترتيب مؤكد
//   no-data = الرد وصل سليم ومفيش ولا ظهور واحد → '-' في الشيت
//   failed  = الطلب فشل → الخانة تفضل فاضية وتتعاد المرة الجاية
//
// scope بيقول الرقم ده بيوصف إيه بالظبط — وده اللي بيخلي التقرير قابل
// للمراجعة في واجهة GSC:
//   page = الصفحة المستهدفة نفسها (يقابل فلتر Query + Page في الواجهة)
//   site = كل صفحات الموقع للكلمة (يقابل فلتر Query لوحده في الواجهة)
function readCell(cls, targetPage, pageMatch) {
  if (!cls || cls.state !== 'ok') {
    return { verdict: 'failed', reason: (cls && cls.reason) || 'مفيش رد',
             position: null, impressions: 0, scope: '', matchMode: 'none' };
  }
  const rows = cls.rows || [];
  // صف صالح = عليه ترتيب أكبر من صفر وظهور واحد على الأقل.
  const valid = rows.filter(r => r && Number(r.position) > 0 && Number(r.impressions) > 0);
  if (!valid.length) {
    return { verdict: 'no-data', reason: rows.length ? 'صفوف من غير ترتيب صالح' : 'مفيش ظهور',
             position: null, impressions: 0, scope: '', matchMode: 'none' };
  }

  // أعلى صفحة ترتيبًا — للتشخيص بس، مش رقم التقرير.
  const best = valid.slice().sort((a, b) => Number(a.position) - Number(b.position))[0];
  const diag = {
    pagesSeen: valid.length,
    topPage: String((best.keys || [])[0] || ''),
    topPagePosition: round1(best.position),
    truncated: !!cls.truncated,
  };

  const want = normUrl(targetPage);
  const hit = want ? (valid.find(r => normUrl((r.keys || [])[0]) === want) || null) : null;

  if (hit) {
    return Object.assign({
      verdict: 'ranked',
      scope: 'page',
      matchMode: 'exact',
      position: round1(hit.position),
      impressions: Math.round(Number(hit.impressions) || 0),
      clicks: Math.round(Number(hit.clicks) || 0),
      matchedPage: String((hit.keys || [])[0] || ''),
    }, diag);
  }

  // الصفحة المستهدفة مش ظاهرة والوضع strict → الخانة تتحسب "مفيش ظهور".
  if (want && pageMatch === 'strict') {
    return Object.assign({
      verdict: 'no-data', reason: 'الصفحة المستهدفة مش ظاهرة',
      position: null, impressions: 0, scope: '', matchMode: 'none',
    }, diag);
  }

  // مفيش صفحة مستهدفة (أو مش ظاهرة والوضع prefer) → رقم الموقع كله للكلمة.
  // ده اللي الواجهة بتعرضه لما تفلتر بالكلمة لوحدها.
  const agg = aggregateRows(valid);
  return Object.assign({
    verdict: 'ranked',
    scope: 'site',
    matchMode: want ? 'site-fallback' : 'site',
    position: round1(agg.position),
    impressions: Math.round(agg.impressions),
    clicks: Math.round(agg.clicks),
    matchedPage: '',
  }, diag);
}

const cfg     = $('Config').first().json;
const tasks   = $('Build Tasks').all();
const results = $('GSC Query').all();

const noFetch = !!(tasks[0] && tasks[0].json && tasks[0].json.__noFetch);
if (noFetch) {
  return [{ json: { __retry: false, retryCount: 0, pass1: { ok: 0, failed: 0, missing: 0 }, noFetch: true } }];
}

const paired = pairResults(tasks, results, cfg.gscRowLimit);

const retry = [];
const summary = { ok: 0, failed: 0, missing: 0 };
tasks.forEach(t => {
  const j = t.json || {};
  if (!j.taskId) return;
  const c = paired.map[j.taskId];
  if (c && c.state === 'ok') { summary.ok++; return; }
  if (c && c.state === 'error') summary.failed++; else summary.missing++;
  retry.push(j);
});

// حد أقصى للمحاولة التانية عشان ماندخلش في لوب طويل لو جوجل واقع خالص.
const MAX_RETRY = 400;
const capped = retry.slice(0, MAX_RETRY);

if (!capped.length) {
  return [{ json: {
    __retry: false, retryCount: 0,
    pass1: summary, pairing: paired.stats,
  } }];
}

return capped.map((j, i) => ({ json: Object.assign({}, j, {
  __retry: true,
  retryIndex: i,
  retryCount: capped.length,
  retryDropped: retry.length - capped.length,
  pass1: summary,
  pairing: paired.stats,
}) }));

// بيدمج أرشيف الشيت مع الخانات اللي اتسحبت دلوقتي، وبيصنّف كل خانة:
//
//   ranked        رقم مؤكد من جوجل                → يتكتب رقم
//   no-data       جوجل رد سليم ومفيش أي ظهور      → يتكتب '-'
//   from-archive  السحبة فشلت والأرشيف فيه رقم    → يتكتب رقم الأرشيف
//   kept-archive  السحبة قالت "مفيش" لعمود قديم   → يتمسك رقم الأرشيف (شبهة)
//   hole          مفيش سحبة ولا أرشيف             → الخانة تفضل فاضية
//
// القاعدة الذهبية: خانة فشل سحبها عمرها ما تتكتب '-' ولا 0 — بتفضل فاضية
// عشان الرن الجاي يعيد يجيبها، والفرق بين "فاضية" و"مفيش ظهور" يفضل واضح.
// ---------------------------------------------------------------------------
// مكتبة الربط والتحقق بين طلبات GSC وردودها.
// (بتتحقن أوتوماتيك في نودات الكود وقت البناء — متعدّلهاش في n8n)
// ---------------------------------------------------------------------------

// n8n بيحط pairedItem على كل عنصر خارج من HTTP Request بيقول جه من أنهي
// عنصر داخل. ده أضمن من الاعتماد على الترتيب، لأن الرد ممكن يتقسّم أو يتلم.
function srcIndex(item, fallbackIndex) {
  const p = item ? item.pairedItem : undefined;
  if (typeof p === 'number') return p;
  if (p && typeof p.item === 'number') return p.item;
  if (Array.isArray(p) && p.length && p[0] && typeof p[0].item === 'number') return p[0].item;
  return fallbackIndex;
}

function errText(e) {
  if (e === undefined || e === null) return '';
  if (typeof e === 'string') return e.slice(0, 300);
  if (e.message) return String(e.message).slice(0, 300);
  try { return JSON.stringify(e).slice(0, 300); } catch (x) { return String(e).slice(0, 300); }
}

// بيصنّف رد واحد من GSC:
//   ok        = رد سليم من جوجل (سواء فيه صفوف أو مفيش)
//   error     = الطلب فشل (429 / 403 / شبكة / توكن)
//   missing   = مفيش رد أصلاً للطلب ده
function classify(res, rowLimit) {
  if (!res) return { state: 'missing', reason: 'مفيش رد للطلب ده' };
  const j = res.json || {};
  if (j.error !== undefined && j.error !== null) {
    return { state: 'error', reason: errText(j.error) || 'خطأ من جوجل' };
  }
  // GSC بيرجّع {} لما مفيش بيانات — ده رد ناجح مش خطأ.
  const rows = Array.isArray(j.rows) ? j.rows : [];
  // الرد بيتقصّ عند rowLimit اللي احنا طلبناه. المقارنة كانت متثبّتة على 900
  // والـ rowLimit الفعلي 500 — يعني الحارس ده عمره ما كان بيشتغل، وأي كلمة
  // ليها صفحات أكتر من الحد كان مجموعها بيطلع ناقص من غير ما حد يعرف.
  const limit = Number(rowLimit) > 0 ? Number(rowLimit) : 0;
  return { state: 'ok', rows, truncated: limit > 0 && rows.length >= limit };
}

// بيربط ردود نود HTTP بطلباتها.
// لو عدد الردود = عدد الطلبات → pairedItem وإلا الترتيب.
// لو العدد مختلف → pairedItem بس، وأي طلب ملقاش رد بيتعلّم missing.
// بنرجّع map من taskIndex → { state, rows | reason }
function pairResults(tasks, results, rowLimit) {
  const strict = results.length !== tasks.length;
  const map = {};
  const stats = { results: results.length, tasks: tasks.length, strict, unpaired: 0 };
  results.forEach((r, i) => {
    const idx = strict ? srcIndex(r, -1) : srcIndex(r, i);
    if (idx < 0 || idx >= tasks.length || !tasks[idx]) { stats.unpaired++; return; }
    const t = tasks[idx].json || {};
    if (t.taskId === undefined) { stats.unpaired++; return; }
    // أول رد بيكسب: لو حصل تكرار في pairedItem مانستبدلش رد سليم بواحد فاشل.
    const c = classify(r, rowLimit);
    if (!map[t.taskId] || (map[t.taskId].state !== 'ok' && c.state === 'ok')) {
      map[t.taskId] = c;
    }
  });
  return { map, stats };
}

// ---- تطبيع الروابط للمقارنة ----
function normUrl(u) {
  let s = String(u == null ? '' : u);
  for (let i = 0; i < 2; i++) {                 // فك ترميز مزدوج لو موجود
    try {
      const d = decodeURIComponent(s);
      if (d === s) break;
      s = d;
    } catch (e) { break; }
  }
  s = s.trim().toLowerCase();
  s = s.replace(/[#?].*$/, '');                 // شيل الأنكور والباراميترز
  s = s.replace(/^https?:\/\//, '').replace(/^www\./, '');
  s = s.replace(/\/index\.(html?|php)$/, '/');
  s = s.replace(/\/+$/, '');
  return s;
}

// ---- تجميع صفوف الصفحات لرقم واحد على مستوى الموقع ----
// جوجل بيرجّع صف لكل صفحة: متوسط موضع الصفحة دي + عدد ظهورها للكلمة.
// الرقم اللي واجهة Search Console بتعرضه للكلمة من غير فلتر صفحة هو المتوسط
// الموزون بعدد الظهور:
//
//     الموضع = مجموع(الموضع × الظهور) ÷ مجموع(الظهور)
//     الظهور = مجموع الظهور
//
// النسخة القديمة كانت بتاخد "أقل موضع" بين الصفحات وظهور الصفحة دي لوحدها.
// ده رقم صفحة واحدة متقفشة من بين ٥٠٠ صفحة — بيطلّع موضع أحسن من الحقيقة
// وظهور أقل منها بكتير. ده بالظبط سبب "POS 10 / IMP 1" في التقرير مقابل
// "20.9 / 144" في الواجهة.
//
// ملحوظة: مجموع الظهور على مستوى الصفحات ممكن يزيد شوية عن رقم الواجهة لو
// أكتر من صفحة من الموقع ظهرت في نفس نتيجة البحث. الرقم المضبوط تمامًا
// بييجي من الصفحة المستهدفة (page) — عشان كده كل كلمة المفروض يكون ليها رابط.
function aggregateRows(rows) {
  let impressions = 0, clicks = 0, weighted = 0;
  rows.forEach(r => {
    const im = Number(r.impressions) || 0;
    impressions += im;
    clicks      += Number(r.clicks) || 0;
    weighted    += Number(r.position) * im;
  });
  return {
    impressions,
    clicks,
    position: impressions > 0 ? weighted / impressions : null,
  };
}

const round1 = v => (v === null || v === undefined) ? null : Math.round(Number(v) * 10) / 10;

// بيطلع نتيجة خانة واحدة من رد جوجل.
// verdict:
//   ranked  = فيه ترتيب مؤكد
//   no-data = الرد وصل سليم ومفيش ولا ظهور واحد → '-' في الشيت
//   failed  = الطلب فشل → الخانة تفضل فاضية وتتعاد المرة الجاية
//
// scope بيقول الرقم ده بيوصف إيه بالظبط — وده اللي بيخلي التقرير قابل
// للمراجعة في واجهة GSC:
//   page = الصفحة المستهدفة نفسها (يقابل فلتر Query + Page في الواجهة)
//   site = كل صفحات الموقع للكلمة (يقابل فلتر Query لوحده في الواجهة)
function readCell(cls, targetPage, pageMatch) {
  if (!cls || cls.state !== 'ok') {
    return { verdict: 'failed', reason: (cls && cls.reason) || 'مفيش رد',
             position: null, impressions: 0, scope: '', matchMode: 'none' };
  }
  const rows = cls.rows || [];
  // صف صالح = عليه ترتيب أكبر من صفر وظهور واحد على الأقل.
  const valid = rows.filter(r => r && Number(r.position) > 0 && Number(r.impressions) > 0);
  if (!valid.length) {
    return { verdict: 'no-data', reason: rows.length ? 'صفوف من غير ترتيب صالح' : 'مفيش ظهور',
             position: null, impressions: 0, scope: '', matchMode: 'none' };
  }

  // أعلى صفحة ترتيبًا — للتشخيص بس، مش رقم التقرير.
  const best = valid.slice().sort((a, b) => Number(a.position) - Number(b.position))[0];
  const diag = {
    pagesSeen: valid.length,
    topPage: String((best.keys || [])[0] || ''),
    topPagePosition: round1(best.position),
    truncated: !!cls.truncated,
  };

  const want = normUrl(targetPage);
  const hit = want ? (valid.find(r => normUrl((r.keys || [])[0]) === want) || null) : null;

  if (hit) {
    return Object.assign({
      verdict: 'ranked',
      scope: 'page',
      matchMode: 'exact',
      position: round1(hit.position),
      impressions: Math.round(Number(hit.impressions) || 0),
      clicks: Math.round(Number(hit.clicks) || 0),
      matchedPage: String((hit.keys || [])[0] || ''),
    }, diag);
  }

  // الصفحة المستهدفة مش ظاهرة والوضع strict → الخانة تتحسب "مفيش ظهور".
  if (want && pageMatch === 'strict') {
    return Object.assign({
      verdict: 'no-data', reason: 'الصفحة المستهدفة مش ظاهرة',
      position: null, impressions: 0, scope: '', matchMode: 'none',
    }, diag);
  }

  // مفيش صفحة مستهدفة (أو مش ظاهرة والوضع prefer) → رقم الموقع كله للكلمة.
  // ده اللي الواجهة بتعرضه لما تفلتر بالكلمة لوحدها.
  const agg = aggregateRows(valid);
  return Object.assign({
    verdict: 'ranked',
    scope: 'site',
    matchMode: want ? 'site-fallback' : 'site',
    position: round1(agg.position),
    impressions: Math.round(agg.impressions),
    clicks: Math.round(agg.clicks),
    matchedPage: '',
  }, diag);
}

const cfg   = $('Config').first().json;
const kws   = $('Keywords').first().json.keywords;
const rs    = $('Read Sheet').first().json;
const hist  = rs.__history || { byRow: {}, monthKeys: [] };
const tasks = $('Build Tasks').all();
const collect = $('Collect Results').first().json || {};

const periods = (tasks[0] && tasks[0].json.__periods) || [];
const noFetch = !!(tasks[0] && tasks[0].json.__noFetch);

// ---------- 1) الربط: السحبة الأولى ثم المحاولة التانية ----------
const cells = {};                       // taskId → classify()
const pairing = { pass1: null, pass2: null };

if (!noFetch) {
  const p1 = pairResults(tasks, $('GSC Query').all(), cfg.gscRowLimit);
  pairing.pass1 = p1.stats;
  Object.keys(p1.map).forEach(k => { cells[k] = p1.map[k]; });

  // نود GSC Retry Query بيشتغل بس لما يبقى فيه طلبات محتاجة إعادة.
  if (Number(collect.retryCount) > 0) {
    const retryTasks = $('Collect Results').all();
    const p2 = pairResults(retryTasks, $('GSC Retry Query').all(), cfg.gscRowLimit);
    pairing.pass2 = p2.stats;
    Object.keys(p2.map).forEach(k => {
      // المحاولة التانية بتستبدل نتيجة فاشلة بس — مش بتلغي نتيجة سليمة.
      if (!cells[k] || cells[k].state !== 'ok') cells[k] = p2.map[k];
    });
  }
}

// ---------- 2) قراءة كل خانة ----------
const fresh = {};
const requestStats = { requested: tasks.length, ranked: 0, noData: 0, failed: 0, truncated: 0,
                       scopePage: 0, scopeSite: 0 };
const failures = [];      // تفاصيل كل خانة فشلت
const pageMisses = [];    // الصفحة المستهدفة متحطة بس مكانتش ظاهرة الأسبوع ده
const noPageKws = {};     // كلمات من غير رابط صفحة مستهدفة أصلاً

if (!noFetch) {
  tasks.forEach(t => {
    const j = t.json || {};
    if (!j.taskId) return;
    const cell = readCell(cells[j.taskId], j.page, cfg.pageMatch);
    fresh[j.taskId] = cell;
    if (!j.page) noPageKws[j.keyword] = 1;
    if (cell.verdict === 'ranked') {
      requestStats.ranked++;
      if (cell.truncated) requestStats.truncated++;
      if (cell.scope === 'page') requestStats.scopePage++; else requestStats.scopeSite++;
      if (j.page && cell.matchMode === 'site-fallback' && pageMisses.length < 200) {
        pageMisses.push({ keyword: j.keyword, period: j.period,
                          expected: j.page, topPage: cell.topPage,
                          pagesSeen: cell.pagesSeen });
      }
    } else if (cell.verdict === 'no-data') {
      requestStats.noData++;
    } else {
      requestStats.failed++;
      if (failures.length < 200) {
        failures.push({ keyword: j.keyword, country: j.countryName,
                        period: j.period, reason: cell.reason });
      }
    }
  });
}

// ---------- 3) الأعمدة: كل اللي في الشيت + أي عمود جديد ----------
const allKeysSet = {};
(hist.monthKeys || []).forEach(k => { allKeysSet[k] = true; });
periods.forEach(p => { allKeysSet[p.key] = true; });
const allKeys = Object.keys(allKeysSet).sort();

// الأعمدة اللي لسه بياناتها ممكن تتغير عند جوجل (آخر VOLATILE_TAIL عمود).
// أي عمود أقدم من كده بياناته مقفولة، فلو السحبة رجعت "مفيش" والأرشيف فيه
// رقم → الأرشيف هو الصح والسحبة هي اللي فيها مشكلة.
const volatile = {};
periods.slice(Math.max(0, periods.length - (cfg.volatileTail || 2))).forEach(p => { volatile[p.key] = true; });

const AR_MON = ['يناير','فبراير','مارس','أبريل','مايو','يونيو',
                'يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر'];
const labelOf = (key) => AR_MON[Number(String(key).split('-')[1]) - 1] || String(key);
const lastLabelOf = (p) => labelOf(p.key);

// ---------- 4) بناء الصفوف ----------
const data = [];        // للتقرير (آخر COLUMNS عمود)
const sheetRows = [];   // للشيت (كل الأعمدة من أول يوم)
const tally = { ranked: 0, noData: 0, fromArchive: 0, keptArchive: 0, holes: 0, archiveOnly: 0 };
const suspicious = [];  // خانات مسكنا فيها الأرشيف رغم إن السحبة قالت "مفيش"

function resolve(rowKey, key, isReportPeriod) {
  const f = fresh[rowKey + '||' + key];
  const o = (hist.byRow[rowKey] || {})[key];
  const archived = o && o.filled;
  const archivedNum = archived && o.position !== null;

  if (f && f.verdict === 'ranked') {
    return { state: 'ranked', position: f.position, impressions: f.impressions,
             cell: f.position, scope: f.scope, matchedPage: f.matchedPage || '' };
  }
  if (f && f.verdict === 'no-data') {
    // عمود قديم + الأرشيف فيه رقم → نمسك الأرشيف ونسجّل شبهة.
    if (archivedNum && !volatile[key]) {
      if (isReportPeriod && suspicious.length < 200) suspicious.push({ rowKey, period: key, archived: o.position });
      return { state: 'kept-archive', position: o.position, impressions: o.impressions, cell: o.position };
    }
    return { state: 'no-data', position: null, impressions: 0, cell: '-' };
  }
  // السحبة فشلت أو مفيش سحبة أصلاً → الأرشيف لو موجود، وإلا خانة فاضية.
  if (archived) {
    return { state: f ? 'from-archive' : 'archive-only',
             position: o.position, impressions: o.impressions,
             cell: o.position === null ? '-' : o.position };
  }
  return { state: 'hole', position: null, impressions: 0, cell: '' };
}

cfg.countries.forEach(c => {
  kws.forEach(k => {
    const rowKey = c.name + '||' + k.keyword;

    // --- الصف الكامل لكل الأعمدة (بيتكتب في الشيت زي ما هو) ---
    const cellsAll = [], imprAll = [];
    allKeys.forEach(mk => {
      const r = resolve(rowKey, mk, false);
      cellsAll.push(r.cell);
      imprAll.push(r.state === 'hole' ? '' : r.impressions);
    });
    sheetRows.push({ country: c.name, section: k.group, keyword: k.keyword,
                     page: k.page || '', article: k.article || '', cellsAll, imprAll });

    // --- أعمدة التقرير بس (السلايدز + الإيميل) ---
    const positions = [], impressions = [], cellsPos = [];
    periods.forEach(p => {
      const r = resolve(rowKey, p.key, true);
      if (r.state === 'ranked')            tally.ranked++;
      else if (r.state === 'no-data')      tally.noData++;
      else if (r.state === 'from-archive') tally.fromArchive++;
      else if (r.state === 'kept-archive') tally.keptArchive++;
      else if (r.state === 'archive-only') tally.archiveOnly++;
      else                                 tally.holes++;
      positions.push(r.position);
      impressions.push(r.impressions || 0);
      cellsPos.push(r.state === 'hole' ? '' : r.cell);
    });

    const li = periods.length - 1;
    const lastCell = periods.length ? fresh[rowKey + '||' + periods[li].key] : null;
    data.push({
      country: c.name, section: k.group, group: k.group + ' — ' + c.name,
      keyword: k.keyword, page: k.page || '', article: k.article || '',
      sv: (k.sv === undefined || k.sv === null) ? '' : k.sv,
      positions, impressionsAll: impressions, cellsPos,
      impressions: impressions[li] || 0,
      // نطاق قياس آخر عمود: 'page' = الصفحة المستهدفة | 'site' = كل صفحات
      // الموقع للكلمة. بيتعرض في السلايد عشان اللي بيراجع يعرف يفلتر نفس
      // الفلتر في واجهة Search Console.
      scope: (lastCell && lastCell.scope) || (k.page ? 'page' : 'site'),
      matchedPage: (lastCell && lastCell.matchedPage) || '',
    });
  });
});

const safe = v => (typeof v === 'number' && !isFinite(v)) ? '' : v;
sheetRows.forEach(r => { r.cellsAll = r.cellsAll.map(safe); r.imprAll = r.imprAll.map(safe); });

const totalCells = data.length * periods.length;
const filled = tally.ranked + tally.noData + tally.fromArchive + tally.keptArchive + tally.archiveOnly;

return [{ json: {
  months: periods.map(p => ({ key: p.key, label: labelOf(p.key), startDate: p.startDate, endDate: p.endDate })),
  data,
  allMonths: allKeys.map(k => ({ key: k, label: labelOf(k) })),
  sheetRows,
  lastMonth: periods.length ? lastLabelOf(periods[periods.length - 1]) : null,
  quality: {
    totalCells, filled,
    coverage: totalCells ? Math.round((filled / totalCells) * 10000) / 10000 : 1,
    tally, requestStats, pairing,
    failures, suspicious, pageMisses,
    keywordsWithoutPage: Object.keys(noPageKws),
    noFetch,
    sheetError: rs.__sheetError || '',
    extent: rs.__extent || { rows: 0, cols: 0 },
    latestDataDate: (tasks[0] && tasks[0].json.__latestDataDate) || '',
    freshnessSource: $('Freshness Guard').first().json.freshnessSource,
    periodsInSheet: (hist.monthKeys || []).length,
    totalPeriodsStored: allKeys.length,
    keywordCount: kws.length,
    invalidEmails: cfg.mailInvalid || [],
  },
} }];

// بوابة جودة البيانات — آخر خط دفاع قبل ما نلمس الشيت أو نبني التقرير.
//
// بتقرر: نكمل ولا نوقف؟ وبتبني كمان مصفوفة القيم اللي هتتكتب في الشيت
// مبطّنة لآخر مقاس كان للشيت، عشان أي أعمدة/صفوف قديمة زايدة تتمسح ومايفضلش
// في الشيت بقايا من قايمة كلمات قديمة.
const cfg = $('Config').first().json;
const res = $input.first().json;
const q   = res.quality || {};

const problems = [];   // أسباب توقف الرن
const warnings = [];   // ملاحظات بتوصل في الإيميل ومابتوقفش الرن

// --- 1) الشيت نفسه ---
if (q.sheetError) {
  problems.push('مقدرناش نقرا الشيت: ' + q.sheetError +
                ' — الكتابة اتوقفت عشان ما نمسحش الأرشيف.');
}

// --- 2) سلامة الربط بين الطلبات والردود ---
const p1 = q.pairing && q.pairing.pass1;
if (p1 && p1.strict) {
  warnings.push('عدد ردود جوجل (' + p1.results + ') مش مساوي عدد الطلبات (' +
                p1.tasks + ') — اتعامل معاها بالربط المؤكد (pairedItem).');
}
if (p1 && p1.unpaired > 0) {
  warnings.push(p1.unpaired + ' رد من جوجل مقدرناش نربطه بطلبه واتجاهل.');
}

// --- 3) التغطية ---
const coverage = Number(q.coverage || 0);
const holes    = Number((q.tally || {}).holes || 0);
const minCov   = Number(cfg.minCoverage);
if (!q.noFetch && coverage < minCov) {
  problems.push('نسبة الخانات المكتملة ' + Math.round(coverage * 1000) / 10 +
                '% وأقل حد مسموح ' + Math.round(minCov * 1000) / 10 + '%.');
}
if (!q.noFetch && holes > Number(cfg.maxHoles)) {
  problems.push('عدد الخانات الفاضية ' + holes + ' وأقصى حد مسموح ' + cfg.maxHoles + '.');
}

// --- 4) أعمدة التقرير ---
const months = res.months || [];
if (!months.length) problems.push('مفيش ولا عمود في التقرير.');
if (months.length < Number(cfg.columns)) {
  warnings.push('التقرير فيه ' + months.length + ' عمود بس بدل ' + cfg.columns +
                ' — عادي لو الشيت لسه جديد أو بيانات جوجل ناقصة.');
}

// --- 5) صحة الأرقام نفسها ---
const badNumbers = [];
(res.data || []).forEach(d => {
  d.positions.forEach((p, i) => {
    if (p === null) return;
    if (!(p > 0) || p > 1000 || !isFinite(p)) {
      badNumbers.push(d.keyword + ' / ' + ((months[i] || {}).key || i) + ' = ' + p);
    }
  });
  (d.impressionsAll || []).forEach((v, i) => {
    if (v !== '' && (!isFinite(v) || v < 0)) {
      badNumbers.push(d.keyword + ' / ظهور ' + ((months[i] || {}).key || i) + ' = ' + v);
    }
  });
});
if (badNumbers.length) {
  problems.push('فيه ' + badNumbers.length + ' رقم خارج المدى المنطقي: ' +
                badNumbers.slice(0, 5).join(' | '));
}

// --- 6) عدد الصفوف ---
const expectedRows = (cfg.countries || []).length * Number(q.keywordCount || 0);
if ((res.data || []).length !== expectedRows) {
  problems.push('عدد صفوف التقرير ' + (res.data || []).length +
                ' والمتوقع ' + expectedRows + '.');
}

// --- 7) ملاحظات مش موقّفة ---
if ((q.tally || {}).keptArchive > 0) {
  warnings.push((q.tally.keptArchive) + ' خانة قديمة رجعت من جوجل "مفيش ظهور" ' +
                'رغم إن الأرشيف فيها رقم — مسكنا رقم الأرشيف لأن بيانات الشهور ' +
                'المقفولة مابتتغيرش.');
}
if ((q.pageMisses || []).length) {
  warnings.push((q.pageMisses.length) + ' خانة الصفحة المستهدفة فيها مكانتش ظاهرة، ' +
                'فالرقم اتحسب على مستوى الموقع كله للكلمة (زي فلتر الكلمة لوحدها ' +
                'في واجهة Search Console) — مش من صفحة تانية.');
}
const noPage = q.keywordsWithoutPage || [];
if (noPage.length) {
  warnings.push(noPage.length + ' كلمة من غير رابط صفحة مستهدفة، فأرقامها على مستوى ' +
                'الموقع كله. لو عايز الرقم يطابق فلتر Query + Page في الواجهة، حط ' +
                'الرابط في seo-reports/extract-keywords.py: ' +
                noPage.slice(0, 8).join(' | ') + (noPage.length > 8 ? ' …' : ''));
}
if ((q.requestStats || {}).truncated > 0) {
  warnings.push(q.requestStats.truncated + ' كلمة رجع فيها عدد صفحات على الحد الأقصى (' +
                cfg.gscRowLimit + ') — يعني فيه صفحات اتقصّت ومجموع الظهور ناقص. ' +
                'ارفع GSC_ROW_LIMIT.');
}
if ((q.invalidEmails || []).length) {
  warnings.push('إيميلات بصيغة غلط واتجاهلت: ' + q.invalidEmails.join(', '));
}
if (q.freshnessSource !== 'gsc') {
  warnings.push('مقدرناش نسأل جوجل عن آخر يوم فيه بيانات، فاستخدمنا LAG_DAYS الاحتياطي.');
}

// --- 8) بناء قيم الشيت مبطّنة لآخر مقاس ---
const header = ['Country', 'Section', 'Keyword', 'Page', 'Article']
  .concat((res.allMonths || []).reduce((a, m) => a.concat([m.key + ' Pos', m.key + ' Impr']), []));

const body = (res.sheetRows || []).map(d =>
  [d.country, d.section, d.keyword, d.page, d.article]
    .concat(d.cellsAll.reduce((a, p, i) => a.concat([p, d.imprAll[i]]), [])));

const values = [header].concat(body);
const oldRows = Number((q.extent || {}).rows || 0);
const oldCols = Number((q.extent || {}).cols || 0);
const width   = Math.max(header.length, oldCols);
values.forEach(r => { while (r.length < width) r.push(''); });
while (values.length < oldRows) values.push(new Array(width).fill(''));

const ok = problems.length === 0;

// --- 9) نص التنبيه لو الرن اتوقف ---
const esc = t => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const li  = arr => arr.map(t => '<li style="margin:0 0 6px 0;">' + esc(t) + '</li>').join('');

const failLines = (q.failures || []).slice(0, 40)
  .map(f => f.keyword + ' — ' + f.period + ' — ' + f.reason);
const failMore = Math.max(0, (q.failures || []).length - failLines.length);

