];
const verifyNote = 'ملحوظة: بيانات جوجل نهائية (final) بس، وأي فلتر ناقص أو زايد ' +
  'بيغيّر الرقم — خصوصًا فلتر الدولة وفلتر الصفحة.' +
  (siteWideCount ? ' في التقرير ده ' + siteWideCount + ' كلمة من غير صفحة مستهدفة (*).' : '');

const html =
