  '<tr><th style="' + th + '">الكلمة</th><th style="' + th + '">القسم</th>' +
  '<th style="' + th + 'text-align:center;">الدولة</th>' +
  '<th style="' + th + 'text-align:center;">عدد مرات البحث</th>' +
